CREATE TABLE tokens(hash TEXT PRIMARY KEY,owner TEXT NOT NULL,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE firms(id TEXT PRIMARY KEY,owner TEXT NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX firms_owner ON firms(owner,created);
CREATE TABLE jobs(id TEXT PRIMARY KEY,firm TEXT NOT NULL REFERENCES firms(id),request_key TEXT NOT NULL,input_hash TEXT NOT NULL,input TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,result TEXT,created INTEGER NOT NULL,UNIQUE(firm,request_key));
CREATE INDEX jobs_firm ON jobs(firm,created);
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT,firm TEXT NOT NULL REFERENCES firms(id),kind TEXT NOT NULL,data TEXT NOT NULL DEFAULT '{}',created INTEGER NOT NULL);
CREATE INDEX events_firm ON events(firm,seq);
CREATE TABLE documents(id TEXT PRIMARY KEY,firm TEXT NOT NULL REFERENCES firms(id),blob TEXT NOT NULL);
CREATE TABLE quotas(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL);
CREATE TABLE reviews(firm TEXT PRIMARY KEY REFERENCES firms(id),revision INTEGER NOT NULL DEFAULT 0,body TEXT NOT NULL);
CREATE TRIGGER firm_limit BEFORE INSERT ON firms WHEN (SELECT count(*) FROM firms WHERE owner=NEW.owner)>=50 BEGIN SELECT RAISE(ABORT,'WORKSPACE_LIMIT'); END;
CREATE TRIGGER job_limit BEFORE INSERT ON jobs WHEN (SELECT count(*) FROM jobs WHERE firm=NEW.firm)>=100 BEGIN SELECT RAISE(ABORT,'JOB_LIMIT'); END;
CREATE TRIGGER job_active BEFORE INSERT ON jobs WHEN (SELECT state FROM firms WHERE id=NEW.firm)!='ACTIVE' BEGIN SELECT RAISE(ABORT,'WORKSPACE_CLOSED'); END;
CREATE TRIGGER document_limit BEFORE INSERT ON documents WHEN (SELECT count(*) FROM documents WHERE firm=NEW.firm)>=20 BEGIN SELECT RAISE(ABORT,'DOCUMENT_LIMIT'); END;
CREATE TRIGGER document_active BEFORE INSERT ON documents WHEN (SELECT state FROM firms WHERE id=NEW.firm)!='ACTIVE' BEGIN SELECT RAISE(ABORT,'WORKSPACE_CLOSED'); END;
CREATE TRIGGER review_active_insert BEFORE INSERT ON reviews WHEN (SELECT state FROM firms WHERE id=NEW.firm)!='ACTIVE' BEGIN SELECT RAISE(ABORT,'WORKSPACE_CLOSED'); END;
CREATE TRIGGER review_active_update BEFORE UPDATE ON reviews WHEN (SELECT state FROM firms WHERE id=NEW.firm)!='ACTIVE' BEGIN SELECT RAISE(ABORT,'WORKSPACE_CLOSED'); END;
